import openmdao.api as om


class Range(om.ExplicitComponent):
    def setup(self):
        self.add_input("mtow", units="kg")
        self.add_input("fuel_fraction")
        self.add_output("range", units="km")
        self.add_output("feasible")

    def compute(self, inputs, outputs):
        outputs["range"] = 36000.0 * inputs["fuel_fraction"]
        outputs["feasible"] = 1.0 if outputs["range"] >= 9000.0 else 0.0
